package com.example.eac_backend_project.Service;
import com.example.eac_backend_project.Service.email.EmailService;
import com.example.eac_backend_project.Service.settings.SettingsService;
import com.example.eac_backend_project.dto.PettyCashRequestDTO;
import com.example.eac_backend_project.dto.PettyCashVoucherDTO;
import com.example.eac_backend_project.entity.finance.PettyCashItem;
import com.example.eac_backend_project.entity.finance.PettyCashRequest;
import com.example.eac_backend_project.entity.finance.PettyCashCycle;
import com.example.eac_backend_project.entity.inventory.User;
import com.example.eac_backend_project.entity.settings.SystemSettings;
import com.example.eac_backend_project.repository.PettyCashRequestRepository;
import com.example.eac_backend_project.repository.PettyCashCycleRepository;
import com.example.eac_backend_project.repository.settings.SystemSettingsRepository;
import com.example.eac_backend_project.utils.EmailRecipientHelper;
import org.springframework.core.io.Resource;
import org.springframework.util.StringUtils;
import org.springframework.web.multipart.MultipartFile;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;

@Service
public class PettyCashService {
 private final PettyCashRequestRepository repository; private final PettyCashCycleRepository cycleRepository; private final SystemSettingsRepository settingsRepository; private final SettingsService settingsService; private final UserService userService; private final EmailService emailService; private final EmailRecipientHelper emailHelper; private final TemplateEngine templateEngine; private final FrontendUrlService frontendUrlService; private final FileStorageService fileStorageService;
 public PettyCashService(PettyCashRequestRepository repository,PettyCashCycleRepository cycleRepository,SystemSettingsRepository settingsRepository,SettingsService settingsService,UserService userService,EmailService emailService,EmailRecipientHelper emailHelper,TemplateEngine templateEngine,FrontendUrlService frontendUrlService,FileStorageService fileStorageService){this.repository=repository;this.cycleRepository=cycleRepository;this.settingsRepository=settingsRepository;this.settingsService=settingsService;this.userService=userService;this.emailService=emailService;this.emailHelper=emailHelper;this.templateEngine=templateEngine;this.frontendUrlService=frontendUrlService;this.fileStorageService=fileStorageService;}

 @Transactional public PettyCashRequest create(PettyCashRequestDTO dto){
  return createForInventory(dto, userService.getCurrentUser(), null, null);
 }
 @Transactional public PettyCashRequest createForInventory(PettyCashRequestDTO dto, User user, Long inventoryId, String inventoryNumber){
  User actor=userService.getCurrentUser(); PettyCashRequest r=new PettyCashRequest(); r.setInventoryRequestId(inventoryId); r.setInventoryRequestNumber(inventoryNumber); r.setCreatedByUserId(actor.getId()); r.setCreatedByName(actor.getName()); r.setReference(ref("PCR")); r.setRequesterId(user.getId()); r.setRequesterName(user.getName()); r.setRequesterEmail(user.getEmail()); r.setCycleId(activeCycle().getId()); r.setCategory(dto.category().trim()); r.setPurpose(dto.purpose().trim()); r.setCostCenter(clean(dto.costCenter())); BigDecimal total=BigDecimal.ZERO;for(var line:dto.items()){PettyCashItem item=new PettyCashItem();item.setRequest(r);item.setDescription(line.description().trim());item.setQuantity(line.quantity());item.setEstimatedUnitCost(line.unitCost());item.setEstimatedTotal(line.quantity().multiply(line.unitCost()));r.getItems().add(item);total=total.add(item.getEstimatedTotal());}if(total.signum()<=0)throw new IllegalArgumentException("Estimated request total must be greater than zero");r.setAmount(total);PettyCashRequest saved=repository.save(r);
  String html=renderMail("Petty cash request submitted","A petty-cash request has been submitted directly to Accounts for review.",saved,null);
  send(user.getEmail(),"Petty cash request received — "+saved.getReference(),html);
  for(String recipient:emailHelper.parseEmailRecipients(settingsService.getSystemSettings().getPettyCashRequestRecipients())) if(!recipient.equalsIgnoreCase(user.getEmail())) send(recipient,"New petty cash request — "+saved.getReference(),html);
  return saved;
 }
 public List<PettyCashRequest> list(boolean canManage){User u=userService.getCurrentUser();return (canManage?repository.findAllByOrderByCreatedAtDesc():repository.findByRequesterIdOrderByCreatedAtDesc(u.getId())).stream().filter(r->InventoryFinanceAccess.visible(r.getInventoryRequestId())).toList();}
 public List<PettyCashRequest> vouchers(){return repository.findByStatusInOrderByProcessedAtDesc(List.of("APPROVED","VOUCHER_COMPLETED")).stream().filter(r->InventoryFinanceAccess.visible(r.getInventoryRequestId())).toList();}
 public Map<String,Object> summary(){PettyCashCycle cycle=activeCycle();BigDecimal used=repository.totalCommittedForCycle(cycle.getId());return Map.of("threshold",cycle.getAllocatedAmount(),"used",used,"remaining",cycle.getAllocatedAmount().subtract(used).max(BigDecimal.ZERO),"cycleId",cycle.getId(),"cycleNumber",cycle.getCycleNumber(),"openedAt",cycle.getOpenedAt());}

 @Transactional public PettyCashRequest approve(Long id,BigDecimal approvedAmount,String notes){
  settingsService.getSystemSettings(); PettyCashRequest r=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Petty cash request not found")); if(!"PENDING_ACCOUNTS".equals(r.getStatus()))throw new IllegalArgumentException("Only pending requests can be approved"); PettyCashCycle cycle=r.getCycleId()==null?activeCycle():cycleRepository.findById(r.getCycleId()).orElseGet(this::activeCycle);r.setCycleId(cycle.getId());if(!"ACTIVE".equals(cycle.getStatus()))throw new IllegalArgumentException("This request belongs to a closed petty-cash cycle");BigDecimal amount=approvedAmount==null?r.getAmount():approvedAmount;if(amount.signum()<=0)throw new IllegalArgumentException("Approved amount must be greater than zero");BigDecimal remaining=cycle.getAllocatedAmount().subtract(repository.totalCommittedForCycle(cycle.getId()));if(amount.compareTo(remaining)>0)throw new IllegalArgumentException("Approval exceeds the remaining petty-cash balance of GHS "+remaining);
  User actor=userService.getCurrentUser();r.setApprovedAmount(amount);r.setStatus("APPROVED");r.setVoucherNumber(ref("PCV"));r.setAccountsNotes(clean(notes));r.setProcessedBy(actor.getName());r.setProcessedAt(LocalDateTime.now());PettyCashRequest saved=repository.save(r);send(saved.getRequesterEmail(),"Petty cash request approved — "+saved.getReference(),renderMail("Petty cash request approved","Your request has been approved by Accounts and a petty-cash voucher has been created.",saved,saved.getAccountsNotes()));return saved;
 }
 @Transactional public PettyCashRequest reject(Long id,String notes){PettyCashRequest r=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Petty cash request not found"));if(!"PENDING_ACCOUNTS".equals(r.getStatus()))throw new IllegalArgumentException("Only pending requests can be rejected");User actor=userService.getCurrentUser();r.setStatus("REJECTED");r.setAccountsNotes(clean(notes));r.setProcessedBy(actor.getName());r.setProcessedAt(LocalDateTime.now());PettyCashRequest saved=repository.save(r);send(saved.getRequesterEmail(),"Petty cash request rejected — "+saved.getReference(),renderMail("Petty cash request not approved","Accounts has completed its review and did not approve this request.",saved,saved.getAccountsNotes()));return saved;}
 @Transactional public Map<String,Object> uploadReceipt(Long id,MultipartFile file) throws java.io.IOException {PettyCashRequest r=find(id);if(!"APPROVED".equals(r.getStatus()))throw new IllegalArgumentException("Receipts can only be uploaded for approved vouchers");if(file==null||file.isEmpty())throw new IllegalArgumentException("Receipt file is required");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Receipt file must not exceed 10 MB");String type=Optional.ofNullable(file.getContentType()).orElse("application/octet-stream");String name=StringUtils.cleanPath(Optional.ofNullable(file.getOriginalFilename()).orElse("receipt"));if(name.contains(".."))throw new IllegalArgumentException("Invalid receipt filename");if(!allowedReceipt(type,name))throw new IllegalArgumentException("Only images, PDF, Word, Excel, or text receipt files are allowed");String oldPath=r.getReceiptReference();String path=fileStorageService.storeFile(file,"petty-cash/"+id);r.setReceiptReference(path);r.setReceiptFileName(name);r.setReceiptContentType(type);r.setReceiptFileSize(file.getSize());r.setReceiptUploadedAt(LocalDateTime.now());repository.save(r);if(oldPath!=null&&!oldPath.equals(path))fileStorageService.deleteFile(oldPath);Map<String,Object> result=new LinkedHashMap<>();result.put("id",id);result.put("reference",id);result.put("fileName",name);result.put("contentType",type);result.put("fileSize",file.getSize());return result;}
 @Transactional(readOnly=true) public Resource receipt(Long id){PettyCashRequest r=find(id);if(r.getReceiptReference()==null)throw new NoSuchElementException("Receipt file not found");return fileStorageService.loadFileAsResource(r.getReceiptReference());}
 @Transactional(readOnly=true) public PettyCashRequest receiptInfo(Long id){return find(id);}
 @Transactional public PettyCashRequest completeVoucher(Long id,PettyCashVoucherDTO dto){PettyCashRequest r=find(id);if(!"APPROVED".equals(r.getStatus()))throw new IllegalArgumentException("Only approved requests can be finalized as vouchers");if(r.getReceiptReference()==null||r.getReceiptReference().isBlank())throw new IllegalArgumentException("Upload the receipt or invoice evidence before finalizing the voucher");if(dto.items().size()!=r.getItems().size())throw new IllegalArgumentException("Voucher must account for every approved request item");BigDecimal actual=BigDecimal.ZERO;for(int i=0;i<r.getItems().size();i++){PettyCashItem item=r.getItems().get(i);var line=dto.items().get(i);if(r.getInventoryRequestId()!=null && (line.quantity().stripTrailingZeros().scale()>0 || line.quantity().compareTo(item.getQuantity())>0))throw new IllegalArgumentException("Inventory voucher quantities must be whole numbers and cannot exceed funded quantities");item.setActualQuantity(line.quantity());item.setActualUnitCost(line.unitCost());item.setActualTotal(line.quantity().multiply(line.unitCost()));actual=actual.add(item.getActualTotal());}if(actual.compareTo(r.getApprovedAmount())>0)throw new IllegalArgumentException("Actual spending cannot exceed the approved amount");User actor=userService.getCurrentUser();r.setActualAmount(actual);r.setPaidTo(dto.paidTo().trim());r.setPaymentMethod(dto.paymentMethod().trim());r.setPaymentReference(clean(dto.paymentReference()));r.setVoucherNotes(clean(dto.notes()));r.setFinalizedBy(actor.getName());r.setFinalizedAt(LocalDateTime.now());r.setStatus("VOUCHER_COMPLETED");PettyCashRequest saved=repository.save(r);send(saved.getRequesterEmail(),"Petty cash voucher completed — "+saved.getVoucherNumber(),renderMail("Petty cash voucher completed","Accounts has recorded the actual payment and completed the voucher.",saved,saved.getVoucherNotes()));return saved;}
 @Transactional public SystemSettings setPurchaseLimit(BigDecimal amount){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Purchase limit must be greater than zero");SystemSettings s=settingsService.getSystemSettings();s.setPettyCashPurchaseLimit(amount);return settingsRepository.save(s);}
 @Transactional public SystemSettings setThreshold(BigDecimal amount){if(amount==null||amount.signum()<0)throw new IllegalArgumentException("Threshold must be zero or greater");SystemSettings s=settingsService.getSystemSettings();s.setPettyCashThreshold(amount);return settingsRepository.save(s);}
 @Transactional public Map<String,Object> reimburse(BigDecimal amount,String reference,String notes){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Reimbursement amount must be greater than zero");PettyCashCycle current=activeCycle();BigDecimal used=repository.totalCommittedForCycle(current.getId());BigDecimal remaining=current.getAllocatedAmount().subtract(used).max(BigDecimal.ZERO);if(remaining.signum()>0)throw new IllegalArgumentException("The current float still has GHS "+remaining+" remaining");User actor=userService.getCurrentUser();current.setStatus("CLOSED");current.setClosedAt(LocalDateTime.now());current.setClosedBy(actor.getName());current.setReimbursementAmount(amount);current.setReimbursementReference(clean(reference));current.setReimbursementNotes(clean(notes));cycleRepository.save(current);PettyCashCycle next=new PettyCashCycle();next.setCycleNumber(ref("PCF"));next.setAllocatedAmount(amount);next.setOpenedBy(actor.getName());cycleRepository.save(next);SystemSettings settings=settingsService.getSystemSettings();settings.setPettyCashThreshold(amount);settingsRepository.save(settings);return cycleMap(next);}
 @Transactional(readOnly=true) public List<Map<String,Object>> cycles(){return cycleRepository.findAllByOrderByOpenedAtDesc().stream().map(this::cycleMap).toList();}
 private String ref(String prefix){return prefix+"-"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"))+"-"+UUID.randomUUID().toString().substring(0,6).toUpperCase();}
 private String clean(String v){return v==null||v.isBlank()?null:v.trim();} private String safe(String v){return v==null?"":v.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
 private PettyCashRequest find(Long id){PettyCashRequest r=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Petty cash request not found"));InventoryFinanceAccess.require(r.getInventoryRequestId());return r;}
 private boolean allowedReceipt(String type,String name){String lower=name.toLowerCase(Locale.ROOT);return type.startsWith("image/")||type.equals("application/pdf")||type.equals("text/plain")||lower.endsWith(".doc")||lower.endsWith(".docx")||lower.endsWith(".xls")||lower.endsWith(".xlsx")||lower.endsWith(".txt");}
 @Transactional protected PettyCashCycle activeCycle(){return cycleRepository.findFirstByStatusOrderByOpenedAtDesc("ACTIVE").orElseGet(()->{BigDecimal allocation=Optional.ofNullable(settingsService.getSystemSettings().getPettyCashThreshold()).orElse(BigDecimal.ZERO);PettyCashCycle cycle=new PettyCashCycle();cycle.setCycleNumber(ref("PCF"));cycle.setAllocatedAmount(allocation);User actor=userService.getCurrentUser();cycle.setOpenedBy(actor==null?"System":actor.getName());PettyCashCycle saved=cycleRepository.save(cycle);for(PettyCashRequest request:repository.findByCycleIdIsNullAndStatusIn(List.of("PENDING_ACCOUNTS","APPROVED","VOUCHER_COMPLETED"))){request.setCycleId(saved.getId());repository.save(request);}return saved;});}
 private Map<String,Object> cycleMap(PettyCashCycle cycle){BigDecimal used=repository.totalCommittedForCycle(cycle.getId());Map<String,Object> value=new LinkedHashMap<>();value.put("id",cycle.getId());value.put("cycleNumber",cycle.getCycleNumber());value.put("allocatedAmount",cycle.getAllocatedAmount());value.put("usedAmount",used);value.put("remainingAmount",cycle.getAllocatedAmount().subtract(used).max(BigDecimal.ZERO));value.put("status",cycle.getStatus());value.put("openedAt",cycle.getOpenedAt());value.put("openedBy",cycle.getOpenedBy());value.put("closedAt",cycle.getClosedAt());value.put("closedBy",cycle.getClosedBy());value.put("reimbursementAmount",cycle.getReimbursementAmount());value.put("reimbursementReference",cycle.getReimbursementReference());value.put("reimbursementNotes",cycle.getReimbursementNotes());value.put("requests",repository.findByCycleIdOrderByCreatedAtDesc(cycle.getId()).stream().filter(r->InventoryFinanceAccess.visible(r.getInventoryRequestId())).toList());return value;}
 private void send(String to,String subject,String html){try{emailService.sendCustomEmail(to,subject,html);}catch(Exception ignored){}}
 private String renderMail(String title,String message,PettyCashRequest request,String notes){SystemSettings settings=settingsService.getSystemSettings();Context c=new Context();c.setVariable("title",title);c.setVariable("message",message);c.setVariable("reference",request.getReference());c.setVariable("voucherNumber",request.getVoucherNumber());c.setVariable("amount",request.getApprovedAmount()!=null?request.getApprovedAmount():request.getAmount());c.setVariable("status",request.getStatus().replace('_',' '));c.setVariable("notes",notes);c.setVariable("actionUrl",frontendUrlService.route("/pettyCash"));c.setVariable("companyName",Optional.ofNullable(settings.getCompanyName()).orElse("EAC System"));c.setVariable("companyEmail",settings.getCompanyEmail());c.setVariable("companyPhone",settings.getCompanyPhone());return templateEngine.process("email/petty-cash-notification",c);}
}
